export const getListSponsorMembersUrl = (sponsorId: string,
    params?: ListSponsorMembersParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/sponsor-organizations/${sponsorId}/members?${stringifiedParams}` : `/api/v1/sponsor-organizations/${sponsorId}/members`
}

